//! Seal for types generated from model-role declarations.

/// Marks a model type generated by a model-role declaration.
///
/// This private supertrait seals [`crate::type_metadata::HasTypeMetadata`] so
/// downstream code cannot implement that trait for arbitrary types. The derive
/// macro supplies this implementation as part of the generated model metadata.
#[doc(hidden)]
pub trait ModelTypeSeal {}
